'use strict';
/* Fast standalone Pro optimizer. Exact Pro execution; indicators computed once, candidates run cheaply. */
const fs=require('fs'),P='data/xauusd-m5-dukascopy.json';
const raw=JSON.parse(fs.readFileSync(P,'utf8')),M=raw.map(x=>({t:+(x.timestamp??x.time),o:+(x.open??x.o),h:+(x.high??x.h),l:+(x.low??x.l),c:+(x.close??x.c)})).filter(x=>[x.t,x.o,x.h,x.l,x.c].every(Number.isFinite)).sort((a,b)=>a.t-b.t);
const day=t=>new Date(t).toISOString().slice(0,10),hour=t=>new Date(t).getUTCHours();
function ema(v,p){const a=Array(v.length).fill(NaN),k=2/(p+1);let e=v[0];for(let i=0;i<v.length;i++){if(i)e=v[i]*k+e*(1-k);if(i>=p-1)a[i]=e}return a}
function rsi(v,p=14){const a=Array(v.length).fill(NaN);let ag=0,al=0;for(let i=1;i<v.length;i++){const d=v[i]-v[i-1],g=Math.max(d,0),l=Math.max(-d,0);if(i<=p){ag+=g;al+=l;if(i===p){ag/=p;al/=p;a[i]=al===0?100:100-100/(1+ag/al)}}else{ag=(ag*(p-1)+g)/p;al=(al*(p-1)+l)/p;a[i]=al===0?100:100-100/(1+ag/al)}}return a}
function atr(c,p=14){const a=Array(c.length).fill(NaN),q=[];let s=0;for(let i=1;i<c.length;i++){const tr=Math.max(c[i].h-c[i].l,Math.abs(c[i].h-c[i-1].c),Math.abs(c[i].l-c[i-1].c));q.push(tr);s+=tr;if(q.length>p)s-=q.shift();if(q.length===p)a[i]=s/p}return a}
function adx(c,p=14){const o=Array(c.length).fill(NaN),tr=Array(c.length).fill(0),pd=Array(c.length).fill(0),md=Array(c.length).fill(0);for(let i=1;i<c.length;i++){const up=c[i].h-c[i-1].h,dn=c[i-1].l-c[i].l;pd[i]=up>dn&&up>0?up:0;md[i]=dn>up&&dn>0?dn:0;tr[i]=Math.max(c[i].h-c[i].l,Math.abs(c[i].h-c[i-1].c),Math.abs(c[i].l-c[i-1].c))}let tn=0,pn=0,mn=0;for(let i=1;i<=p;i++){tn+=tr[i];pn+=pd[i];mn+=md[i]}const dx=Array(c.length).fill(NaN);for(let i=p;i<c.length;i++){if(i>p){tn=tn-tn/p+tr[i];pn=pn-pn/p+pd[i];mn=mn-mn/p+md[i]}if(tn>0){const a=100*pn/tn,b=100*mn/tn;if(a+b>0)dx[i]=100*Math.abs(a-b)/(a+b)}}let seed=0,n=0,last=NaN;for(let i=p;i<c.length;i++){if(!Number.isFinite(dx[i]))continue;if(n<p){seed+=dx[i];n++;if(n===p)last=o[i]=seed/p}else last=o[i]=(last*(p-1)+dx[i])/p}return o}
function aggregate(src,ms){const out=[];let z=null,k0=null;for(const x of src){const k=Math.floor(x.t/ms)*ms;if(k!==k0){if(z)out.push(z);z={t:k,o:x.o,h:x.h,l:x.l,c:x.c};k0=k}else{z.h=Math.max(z.h,x.h);z.l=Math.min(z.l,x.l);z.c=x.c}}if(z)out.push(z);return out}
const C=M.map(x=>x.c),R=rsi(C),A=atr(M),X=adx(M),D=aggregate(M,864e5),DC=D.map(x=>x.c),DE50=ema(DC,50),dIdx=Array(M.length).fill(-1);let dp=0;for(let i=0;i<M.length;i++){while(dp+1<D.length&&D[dp+1].t+864e5<=M[i].t)dp++;dIdx[i]=(D[dp]&&D[dp].t+864e5<=M[i].t)?dp:-1}
const AA=Array(M.length).fill(NaN);for(let i=50;i<M.length;i++){let s=0,n=0;for(let j=i-50;j<i;j++)if(Number.isFinite(A[j])){s+=A[j];n++}if(n===50)AA[i]=s/50}
function stats(a){const n=a.length,w=a.filter(x=>x.r>0).length,g=a.filter(x=>x.r>0).reduce((s,x)=>s+x.r,0),l=-a.filter(x=>x.r<0).reduce((s,x)=>s+x.r,0),net=a.reduce((s,x)=>s+x.r,0);let e=0,pk=0,dd=0,ls=0,mx=0;for(const x of a){e+=x.r;pk=Math.max(pk,e);dd=Math.max(dd,pk-e);if(x.r<0){ls++;mx=Math.max(mx,ls)}else ls=0}return{n,wr:n?100*w/n:0,pf:l?g/l:(g?999:0),net,dd,ls:mx}}
function run(q){let a=[],p=null,lossDay=null,losses=0,cool=0;for(let i=250;i<M.length-1;i++){const now=M[i].t,dy=day(now);if(lossDay!==dy){lossDay=dy;losses=0}if(p){const b=M[i],sl=p.side==='BUY'?b.l<=p.sl:b.h>=p.sl;let px=null;if(sl)px=p.sl;else if(p.side==='BUY'&&R[i]>=58)px=b.c;else if(p.side==='SELL'&&R[i]<=45)px=b.c;else{const z=new Date(now);if(z.getUTCDay()===5&&(z.getUTCHours()*60+z.getUTCMinutes())>=1305)px=b.c}if(px!=null){const rr=(p.side==='BUY'?px-p.en:p.en-px)/12;a.push({r:rr,side:p.side});if(rr<0){losses++;cool=now+180*60000}p=null}}if(p||losses>=2||now<cool)continue;const d=dIdx[i];if(d<49||![R[i-1],R[i],X[i],A[i],DE50[d],AA[i]].every(Number.isFinite))continue;const z=new Date(now),min=z.getUTCHours()*60+z.getUTCMinutes();if(z.getUTCDay()===3&&min>=1020&&min<=1230)continue;const bias=DC[d]>DE50[d]?'BUY':'SELL',ratio=A[i]/AA[i];let side=null;if(R[i-1]>=41&&R[i]<41&&bias==='BUY'&&X[i]>=q.ba&&ratio<=q.br)side='BUY';if(R[i-1]<=63&&R[i]>63&&bias==='SELL'&&X[i]>=q.sa&&ratio<=q.sr)side='SELL';if(!side)continue;if(side==='BUY'&&hour(now)===8)continue;const b=M[i],rg=b.h-b.l;if(!(rg>0)||Math.abs(b.c-b.o)/rg<q.body)continue;if(side==='BUY'&&(i<36||b.c-M[i-36].c<q.mom))continue;const en=M[i+1].o;p={side,en,sl:side==='BUY'?en-12:en+12}}if(p){const px=M.at(-1).c;a.push({r:(p.side==='BUY'?px-p.en:p.en-px)/12,side:p.side})}return stats(a)}
const BASE={ba:27,br:1.30,sa:19,sr:1.15,mom:-20,body:.5},base=run(BASE),F=s=>`T${s.n} WR${s.wr.toFixed(1)} PF${s.pf.toFixed(2)} N${s.net>=0?'+':''}${s.net.toFixed(2)}R DD${s.dd.toFixed(2)} LS${s.ls}`;console.log('PRO — FAST STANDALONE BUY+SELL SEARCH');console.log('BASE',F(base));if(base.n!==239){console.log('❌ BASE PARITY FAIL — expected T239');process.exit(3)}console.log('✅ BASE PARITY OK');
const out=[];for(const ba of [23,25,27,29])for(const br of [1.05,1.15,1.30])for(const sa of [17,19,21,23])for(const sr of [1,1.15,1.30])for(const mom of [-30,-20,-10,0])for(const body of [.45,.5,.6]){const q={ba,br,sa,sr,mom,body},m=run(q);if(m.n>=150&&m.pf>=1.5&&m.dd<=6)out.push({q,m})}out.sort((x,y)=>y.m.wr-x.m.wr||y.m.pf-x.m.pf||y.m.net-x.m.net);console.log(`TESTED 1728 | RETAINED ${out.length}`);out.slice(0,20).forEach((x,i)=>console.log(`#${i+1} BUY ADX${x.q.ba} ATR${x.q.br} MOM${x.q.mom} | SELL ADX${x.q.sa} ATR${x.q.sr} | BODY${x.q.body} => ${F(x.m)}`));
